body_md:
Let $u$ be a weak solution of a quasi-linear parabolic equation
  \begin{equation}\label{1.2}
  \begin{array}{l}
  \begin{split}
    -\partial_{t}u=\partial_{x_i} \mathscr{A}_i(t,x,u,\nabla u)+\mathscr{B}(t,x,u,\nabla u)
    \end{split}
  \end{array}
 \end{equation}
  in the bounded cylinder $Q=(0,T)\times\mathcal{O}\subset \mathbb{R}^{1+n}$ such that $u\leq M$ on the parabolic boundary $\left((0,T]\times \mathcal{O}\right)\cup\left( \{T\}\times \mathcal{O} \right)$.
  Then almost everywhere in $Q$
  $$u\leq M +C \Xi(\mathscr{A},\mathscr{B}) $$
  where the constant $C$ depends only on $T,|\mathcal{O}|$ and the structure terms of the equation, while $\Xi(\mathscr{A},\mathscr{B})$ is expressed in terms of some quantities related to the coefficients $\mathscr{A}$ and $\mathscr{B}$.

\label{lem emmbedding for space V}
   For $u\in \dot{\mathcal{V}}_{2}(\Pi_t )$ with $t\in [0,T)$, we have $u\in \mathcal{M}^{\frac{2(n+2)}{n}}(\Pi_t )$ and
   \begin{equation*}
     \begin{split}
       \|u\|_{\frac{2(n+2)}{n};\Pi_t }\leq\,&
         \ C(n) ~\|\nabla u\|_{2;\Pi_t }^{n/(n+2)}
          \operatorname*{ess\,sup}_{(\omega,s)\in\Omega\times[t,T]}\|u(\omega,s,\cdot)\|_{L^2(\Pi)}^{2/(n+2)}
         \leq\  C(n)~ \|u\|_{\mathcal{V}_2(\Pi_t )}.
     \end{split}
   \end{equation*}

By the well known Gagliard-Nirenberg inequality (c.f. \cite{FriedmanPDEs}, \cite{Ladyzhenskaia_68} or \cite{Nirenberg1959}), we have
  \begin{equation*}
    \|u(\omega,s,\cdot)\|_{L^q(\Pi)}^q
    \leq\  C~
        \|\nabla u(\omega,s,\cdot)\|_{L^2(\Pi)}^{\alpha q}\|u(\omega,s,\cdot)\|_{L^2(\Pi)}^{q(1-\alpha)},
        \quad a.e.\ (\omega,s)\in\Omega\times[t,T],
  \end{equation*}
  where $\alpha=n/(n+2)$ and $q=2(n+2)/n$.
  Integrating on $[\tau,T]$ for $\tau\in [t,T)$ and taking conditional expectation, we obtain almost surely
  \begin{equation*}
    \begin{split}
    E\left[\int_{\Pi_{\tau} }|u(s,x)|^qdxds\Big|\mathscr{F}_{\tau} \right]
    \leq &\ C~
    \|\nabla u\|_{2;\Pi_t }^{2}
        \operatorname*{ess\,sup}_{(\omega,s)\in\Omega\times[t,T]}\|u(\omega,s,\cdot)\|_{L^2(\Pi)}^{(1-\alpha) q}
    \leq \ C~
        \|u\|^q_{\mathcal{V}_2(\Pi_t )}.
    \end{split}
  \end{equation*}
Therefore,  $u\in \mathcal{M}^{\frac{2(n+2)}{n}}(\Pi_t )$ and
   \begin{equation*}
     \begin{split}
       \|u\|_{\frac{2(n+2)}{n};\Pi_t }\leq&
         \ C ~\|\nabla u\|_{2;\Pi_t }^{n/(n+2)}
          \operatorname*{ess\,sup}_{(\omega,s)\in\Omega\times[t,T]}\|u(\omega,s,\cdot)\|_{L^2(\Pi)}^{2/(n+2)}
         \leq\  C~ \|u\|_{\mathcal{V}_2(\Pi_t )}
     \end{split}
   \end{equation*}
   with $C$ only depending on $n$.

All the integrals in \eqref{eq ito lemma} are well defined.
   In particular, the stochastic integral
   $$I(t):=\int_0^t\ll \phi'(s,\cdot,u(s)),\, z^r(s)\gg dW_s^r, \quad t\in [0,T]$$ is a martingale
   since
  \begin{equation*}
    \begin{split}
      E\left[\sup_{t\in [0,T]}\left|I(t)\right|\right]\le
     &\, CE\left[\left(\int_0^T\Bigm |\ll |\phi'(s,\cdot,u(s))|,\,|z(s)|\gg \Bigm|^2ds\right)^{1/2}\right]\\
     \leq &
     \, CM \|u\|_{S^2(L^2(\mathcal{O}))}\|z\|_{W^2_{\mathscr{F}}(Q)}.
    \end{split}
  \end{equation*}
    We extend the random fields $u,h^0,h^1,\cdots,h^n$ and $z$ from their domain $\Omega\times [0,T]\times \mathcal{O}$ to  $\Omega\times [0,T]\times \mathbb{R}^n$
    by setting them all to be zero outside $\mathcal{O}$, and we still use themselves to denote their respective extensions. Since $u$ satisfies the
    null Dirichlet condition on the lateral boundary and $\partial\mathcal{O}\in C^1$, we have $u\in W^{1,2}_{\mathscr{F}}([0,T]\times \mathbb{R}^n)$. It is obvious that all the
    extensions $h^0,h^1,\cdots,h^n$ and $z$ lie in $W^2_{\mathscr{F}}([0,T]\times \mathbb{R}^n)$.


  \textbf{Step 1.}
  Consider $h^i\in \dot{W}^{1,2}_{\mathscr{F}}(\mathcal{O})$, $i=1,2,\cdots,n$.
  Choose a sufficiently large positive integer $N_0$  so that $\{x\in\mathcal{O}:dis(x,\partial\mathcal{O})>1/N_0\}$ is a nonempty sub-domain of $\mathcal{O}$.
  For integer $N>N_0$, define
  $$\mathcal{O}^N:=\{x\in\mathcal{O}:dis(x,\partial\mathcal{O})>1/N\}.$$
  Let $\rho\in C_c^{\infty}(\mathbb{R}^n)$ be a nonnegative function such that
  $$\textrm{supp} ({\rho})\subset B_1(0) \hbox{ \rm and } \int_{\mathbb{R}^n}\rho(x)\, dx=1.$$
   Define for each positive integer $k$,
   $$\rho_k(x):=(2Nk)^n\rho(2Nkx),\quad u_k(s,x):=u(s)\ast \rho_k(x):=\int_{\mathbb{R}^n}\rho_k(x-y)u(s,y)\,dy.$$
  In a similar way, we write
  $$z_k(s,x):=z(s)\ast\rho_k(x) \hbox{ \rm  and } h^i_k(s,x):=h^i(s)\ast\rho_k(x), \, \, i=1,2,\cdots,n.$$
  Then for each $x\in \mathcal{O}^N$, we have almost surely
  $$u_k(t,x)=u_k(T,x)+\int_t^T\left(\partial_{x_i} h_k^i(s,x)+h_k^0(s,x)\right)\,ds-\int_t^Tz_k^r(s,x)\,dW_s^r, ~\forall t\in [0,T].   $$
 By using It\^o formula for each $x\in\mathcal{O}^N$  and then integrating over $\mathcal{O}^N$ with respect to $x$ , we obtain
  \begin{equation}\label{eq 2 in ito formula}
   \begin{split}
     &\int_{\mathcal{O}^N}\phi(t,x,u_k(t,x))\, dx \\ =&\int_{\mathcal{O}^N}\!\phi(T,x,u_k(T,x))\, dx
     -\int_t^T\!\!\!\int_{\mathcal{O}^N}\partial_{s}\phi(s,x,u_k(s,x))\, dxds\\
     &
     +\int_t^T\ll \phi'(s,\cdot,u_k(s)),\ \, h^0(s)\gg_{\mathcal{O}^N} ds
     \\
     &+\int_t^T\ll \phi'(s,\cdot,u_k(s)),\ \, \partial_{x_i} h_k^i(s)\gg_{\mathcal{O}^N} ds              \\
     &-\frac{1}{2}\int_t^T \ll \phi''(s,\cdot,u_k(s)),\ \, |z_k(s)|^2\gg_{\mathcal{O}^N} ds\\
     &-\int_t^T\ll \phi'(s,\cdot,u_k(s)),\ \, z_k^r(s)\gg_{\mathcal{O}^N} dW_s^r.
   \end{split}
 \end{equation}

For the sake of convenience, we define
\begin{equation*}
  \begin{split}
    \delta\phi_k(t,x):=&\phi(t,x,u(t,x))-\phi(t,x,u_k(t,x))\\
    \delta u_k(t,x):=& u(t,x)-u_k(t,x).
  \end{split}
\end{equation*}
                                                                                          
and in a similar way, we define $\delta \phi_k',\delta\phi_k'',\delta h_k^i$ and $\delta z_k^r$ $i=0,1,\cdots,n;r=1,\cdots,m$.

  Since for almost all $(\omega,s)\in\Omega\times[0,T]$
 \begin{equation*}
   \begin{split}
     &\|u_k(\omega,s)\|_{W^{1,2}(\mathbb{R}^n)}\leq\|u(\omega,s)\|_{W^{1,2}(\mathbb{R}^n)},
     ~\lim_{k\rightarrow\infty}\|\delta u_k(\omega,s)\|_{W^{1,2}(\mathbb{R}^n)}\rightarrow 0;\\
     &\|h^0_k(\omega,s)\|_{L^2(\mathbb{R}^n)}\leq\|h^0(\omega,s)\|_{L^2(\mathbb{R}^n)},
     ~\lim_{k\rightarrow\infty}\|\delta h^0_k(\omega,s)\|_{L^{2}(\mathbb{R}^n)}\rightarrow 0;\\
     &\|h^i_k(\omega,s)\|_{W^{1,2}(\mathbb{R}^n)}\leq\|h^i(\omega,s)\|_{W^{1,2}(\mathbb{R}^n)},
     ~\lim_{k\rightarrow\infty}\|\delta h^i_k(\omega,s)\|_{W^{1,2}(\mathbb{R}^n)}\rightarrow 0,i=1,2,\cdots;\\
     &\|z_k(\omega,s)\|_{L^2(\mathbb{R}^n)}\leq\|z(\omega,s)\|_{L^2(\mathbb{R}^n)},
     ~\lim_{k\rightarrow\infty}\|\delta z_k(\omega,s)\|_{L^{2}(\mathbb{R}^n)}\rightarrow 0,
   \end{split}
 \end{equation*}
 by Lebesgue's dominated convergence theorem, we have as $k\rightarrow \infty$
 \begin{equation*}
   \begin{split}
      &\sum_{i=1}^n\|\delta h^i_k(s)\|^2_{W_{\mathscr{F}}^{1,2}([0,T]\times \mathbb{R}^n)}+\|\delta h^0_k(s)\|^2_{W^2_{\mathscr{F}}([0,T]\times \mathbb{R}^n)} +\|\delta z_k(s)\|_{W_{\mathscr{F}}^2([0,T]\times \mathbb{R}^n)}^2\\
      &+\|\delta u_k(s)\|_{W_{\mathscr{F}}^{1,2}([0,T]\times \mathbb{R}^n)}^2\rightarrow 0,
   \end{split}
 \end{equation*}
\begin{equation*}
  \begin{split}
        &E\left[\int_0^T\!\!\!\int_{\mathcal{O}}\left|\delta\phi_k(t,x)\right|\, dxdt\right]
        \leq
        E\left[\int_0^T M\ll |u_k(t)|+|u(t)|,\, |\delta u_k(t)|\gg dt\right]\rightarrow 0,
  \end{split}
\end{equation*}
\begin{equation*}
  \begin{split}
    &E\left[\int_0^T\!\!\!\int_{\mathbb{R}^n}\big|\phi'(s,x,u_k(s,x))\partial_{x_i} h_k^i(s,x)
    -\phi'(s,x,u(s,x))\partial_{x_i} h^i(s,x)\big|\, dxds\right]\\
    \leq&
        \ E\bigg[\int_0^T\!\!\!\int_{\mathbb{R}^n}\Big(M\big|\delta u_k(s,x)\partial_{x_i} h^i_k(s,x)\big| +M|u(s,x)|\left|\partial_{x_i} (\delta h^i_k)(s,x)\right|\Big)\, dxds
        \bigg]
        \rightarrow 0,\\
        &\ i=1,\cdots,n
  \end{split}
\end{equation*}
and
\begin{equation*}
    \begin{split}
         &E\left[\int_0^T\!\!\!\int_{\mathbb{R}^n}|\phi'(s,x,u_k(s,x))h_k^0(s,x)-\phi'(s,x,u(s,x))h^0(s,x)|\, dxds\right]\\
    \leq&
        E\left[\int_0^T\!\!\!\int_{\mathbb{R}^n}\big(M|\delta u_k(s,x)h^0_k(s,x)|
        +M|u(s,x)||\delta h^0_k(s,x)|\big)\, dxds\right]
        \rightarrow 0.
    \end{split}
\end{equation*}

Since the convergence
$$\lim_{k\rightarrow \infty}\|\delta u_k\|_{W^{1,2}_{\mathscr{F}}([0,T]\times\mathbb{R}^n)}=0$$
implies that $u_k(\omega,t,x)$ converges to $u(\omega,t,x)$ in measure $dP\otimes dt \otimes dx$,
from the dominated
convergence theorem we conclude that
$$
    \lim_{k\rightarrow\infty}
     E\left[\int_0^T\!\!\!\int_{\mathcal{O}}\,|{\partial_{s}}\phi(s,x,u_{k}(s,x))\,
    -\partial_{s}\phi(s,x,u(s,x))|\,
        \,dxds\right]=0.
$$
In a similar way,  we obtain
\begin{equation*}
  \begin{split}
    E\left[\int_0^T\!\!\!\int_{\mathcal{O}}\Big|\phi''(s,x,u(s,x))|z(s,x)|^2
    -\phi''(s,x,u_k(s,x))|z_k(s,x)|^2\Big|\,dxds\right]\rightarrow 0
  \end{split}
\end{equation*}
and
 \begin{equation*}
   \begin{split}
        &E\left[\sup_{t\in[0,T]}\left|
        \sum_{r=1}^m
        \int_t^T\!\!\!\int_{\mathbb{R}^n}
        \left(
        \phi'(s,x,u_k(s,x))z^r_k(s,x)
        -\phi'(s,x,u(s,x))z^r(s,x)\right)\,dxdW^r_s   \right|   \right]\\
     \leq&
        \ CE\left[\left(\int_0^T\left|\ll \phi'(s,\cdot,u_k(s)),\ z_k(s)\gg_{\mathbb{R}^n}
        -\ll \phi'(s,\cdot,u(s)),\ z(s)\gg_{\mathbb{R}^n} \right|^2\,ds\right)^{1/2} \right]\\
     \leq&
        \ CE\biggl[\Bigl(\int_0^T\big( \|\delta u_k(s)\|_{L^2(\mathbb{R}^n)}^2 \|z(s)\|^2_{L^2(\mathbb{R}^n)}
        + \|\phi'(s,u_k(s))\|^2_{L^2(\mathbb{R}^n)} \|\delta z_k(s)\|^2_{L^2(\mathbb{R}^n)} \big)\,ds\Bigr)^{1/2} \biggr]\\
        &\longrightarrow 0\textrm{ as }k\rightarrow \infty.
   \end{split}
 \end{equation*}
Hence taking limits in $L^1(\Omega\times[0,T],\mathscr{P})$ as $k\rightarrow \infty$ on both sides of \eqref{eq 2 in ito formula} and noting the path-wise continuity of $u$, we have almost surely
 \begin{equation}\label{eq N in ito lemma}
   \begin{split}
     &\int_{\mathcal{O}^N}\phi(t,x,u(t,x))\, dx             \\
     =&\int_{\mathcal{O}^N}\phi(T,x,u(T,x))\, dx
     -\int_t^T\!\!\!\int_{\mathcal{O}^N} \partial_{s}\phi(s,x,u(s,x)) \,dxds \\
     &+
     \int_t^T\ll \phi'(s,\cdot,u(s)),\ \, h^0(s) \gg_{\mathcal{O}^N} ds
     \\
     &+\int_t^T\ll\phi'(s,\cdot,u(s)),\ \,\partial_{x_i} h^i(s)\gg_{\mathcal{O}^N} ds              \\
     &-\frac{1}{2}\int_t^T \ll \phi''(s,\cdot,u(s)),\ \,|z(s)|^2\gg_{\mathcal{O}^N}ds\\
     &-\int_t^T\ll \phi'(s,\cdot,u(s)),\ \, z^r(s)\gg_{\mathcal{O}^N} dW_s^r,\quad \forall\  t\in[0,T].
   \end{split}
 \end{equation}
  Passing to the limit in $L^1(\Omega\times[0,T],\mathscr{P})$ by letting $N\rightarrow \infty$ on both sides of \eqref{eq N in ito lemma}, in view of  the path-wise continuity of $u$ and the integration-by-parts formula, we conclude
  \eqref{eq ito lemma}.

  \textbf{Step 2.}
  For the general $h^i\in W_{\mathscr{F}}^2(Q)$, we choose  sequences $\{h^i_k\}$, $\{z^r_k\}$ and $\{u_k\}$ from $S^2(\mathbb{R})\otimes C_c^{\infty}(\mathcal{O})$ such that
  \begin{equation*}
    \begin{split}
      \lim_{k\rightarrow\infty}\bigg\{
      &\sum_{i=0}^n \|\delta h_k^i\|_{W^{2}_{\mathscr{F}}(Q)} +\|\delta z_k\|_{W_{\mathscr{F}}^2(Q)}
          +\|\delta u_k\|_{W^{1,2}_{\mathscr{F}}(Q)} +\|\delta u_k(0)\|_{L^2(\mathcal{O})}   \bigg\}=0.
    \end{split}
  \end{equation*}
  Consider
  \begin{equation}\label{eq step2 in ito thm}
    \begin{split}
      \bar{u}(t,x)=\, &u(0,x)+\int_0^t\left(\Delta \bar{u}(s,x)+\partial_{x_i} \tilde{h}^i(s,x)-h^0(s,x)\right)\, ds\\
      &+\int_0^t z^r(s,x)\, dW^r_s, \quad t\in [0,T]
    \end{split}
  \end{equation}
  with
  $$\tilde{h}^i(s,x):=-\partial_{x_i}  u(s,x)-h^i(s,x).$$
                                                                                                             
    From Remark \ref{rmk defn weak solution} and \cite[Theorem 2.1]{Denis2004},  there are unique weak solutions $u\in \dot{W}^{1,2}_{\mathscr{F}}(Q)\cap S^2(L^2(\mathcal{O}))$
     to SPDE \eqref{eq step2 in ito thm}
   in the sense of \cite[Definition 1]{Denis2004} or equivalently \cite[Definition 4]{DenisMatoussiStoica2005}), and
    $u^k\in \dot{W}^{1,2}_{\mathscr{F}}(Q)\cap S^2(L^2(\mathcal{O}))$  to SPDE \eqref{eq step2 in ito thm}
    with $u(0,x)$, $z(s,x)$ and $\tilde{h}^i(s,x)$ being replaced by $u_k(0,x)$, $z_k(s,x)$ and
   $$\tilde{h}_k^i(s,x):=-\partial_{x_i}  u_k(s,x)-h_k^i(s,x), \quad k=1,2,\cdots.$$
   Then
   we deduce from \cite[Propositions 6 and 7, and Theorem 9]{Denis2004} that $u^k\in W^{2,2}_{\mathscr{F}}(Q)\cap \dot{W}^{1,2}_{\mathscr{F}}(Q)\cap S^2(L^2(\mathcal{O})) $ and
  \begin{equation}
  \begin{split}
  &\lim_{k\rightarrow\infty}\{\|u^k-u\|_{W_{\mathscr{F}}^{1,2}(Q)}+\|u^k-u\|_{S^2(L^2(\mathcal{O}))}\} \\
  \leq & \ C\lim_{k\rightarrow\infty}\{\|\delta u_k \|_{W_{\mathscr{F}}^2(Q)}
  + \|\delta z_k\|_{W_{\mathscr{F}}^2(Q)}
  +\|\delta u_k(0)\|_{L^2(\mathcal{O})}
  + \sum_{i=0}^n\|\delta h_k^i\|_{W_{\mathscr{F}}^2(Q)}\}      \\
  =&\ 0
  \end{split}
  \end{equation}
  with the constant $C$ being independent of $k$.
  For each $k$, by \textbf{Step 1} we have
   \begin{equation*}
   \begin{split}
     &\int_{\mathcal{O}}\phi(t,x,u^k(t,x))\, dx \\
     =&\int_{\mathcal{O}}\phi(T,x,u^k(T,x))\, dx-\int_t^T\!\!\!\int_{\mathcal{O}}\partial_{s}\phi(s,x,u^k(s,x))
     \,dxds\\
     &+\int_t^T\ll
     \phi'(s,\cdot,u^k(s)),\ \,h_k^0(s)\gg ds\\
     &+\int_t^T \ll
     \phi''(s,\cdot,u^k(s))\partial_{x_i} u^k(s)+
     \partial_{x_i} \phi'(s,\cdot,u^k(s)),\ \, \partial_{x_i} u^k(s)
                        \gg ds             \\
     &+\int_t^T\ll
     \phi''(s,\cdot,u^k(s))\partial_{x_i} u^k(s)+
     \partial_{x_i} \phi'(s,\cdot,u^k(s)),\ \,
     \tilde{h}_k^i(s)
                        \gg ds              \\
     &-\frac{1}{2}\int_t^T\ll
     \phi''(s,\cdot,u^k(s)),\, |z_k(s)|^2
                        \gg ds
     -\int_t^T\ll
     \phi'(s,\cdot,u^k(s)),\, z_k^r(s)
                        \gg dW_s^r,
   \end{split}
 \end{equation*}
  for all $t\in [0,T]$, $P$-a.s..
  By taking limits as $k\rightarrow \infty$,
  we complete our proof.

\label{lem ito for non null bdary condition}
                                                                                                                                          
Let all the assumptions on $\phi$ of Lemma \ref{lem ito foumul} be satisfied. If the function $u$ in   \eqref{eq bspde in ito formula}
belongs to $ W^{1,2}_{\mathscr{F}}(Q)\cap S^2(L^2(Q))$ with $u^+\in \dot{W}^{1,2}_{\mathscr{F}}(Q)$, we have almost surely
\begin{equation}
  \begin{split}
    &\int_{\mathcal{O}}\phi(t,x,u^+(t,x))\, dx+\frac{1}{2}\int_t^T\ll\phi''(s,\cdot,u^+(s)),\,|z^u(s)|^2\gg\, ds\\
    =&
    \int_{\mathcal{O}}\phi(T,x,u^+(T,x))\, dx-\int_t^T\!\!\!\int_{\mathcal{O}}\partial_{s}\phi(s,x,u^+(s,x))\, dxds\\
    &+\int_t^T\ll\phi(s,\cdot,u^+(s)),\, h^{0,u}(s)\gg\, ds               \\
    &-\int_{t}^T\ll\phi''(s,\cdot,u^+(s))\partial_{x_i} u^+(s)
    +\partial_{x_i} \phi'(s,\cdot,u^+(s)),\quad h^{i,u}(s)\gg\, ds\\
    &-\int_t^T\ll\phi'(s,\cdot, u^+(s)),\,\ z^{r,u}(s)\gg\, dW_s^r,\,\quad  t\in [0,T]
  \end{split}
\end{equation}
with
  $$h^{i,u}:=1_{\{u>0\}}h^i,\quad i=0,1,\cdots,n$$
and $$ z^{r,u}=1_{\{u>0\}}z^r,\quad r=1,\cdots,m; \quad z^u:=(z^{1,u}, \cdots, z^{m,u}).$$

\label{thm solve (1.1)}
  Let assumptions $({\mathcal A}1)$--$({\mathcal A}3)$ be satisfied and $\left\{h^i,i=0,1,\cdots,n\right\}\subset \mathcal{M}^2(Q)$.  Then  $\dot{\mathscr{U}}\times\dot{\mathscr{V}}(G,f+h,g+h^0)$ (with $h=(h^1,\cdots,h^n)$) admits one and only one element $(u,v)$ which satisfies
   the following estimate 
    \begin{equation}\label{estimates in thm general existence}
      \begin{split}
        \|u\|_{\mathcal{V}_2(Q)}+\|v\|_{\mathcal{M}^2(Q)}\leq C \left\{\|G\|_{L^{\infty}(\Omega,\mathscr{F}_T,L^2(\mathcal{O}))}
        +A_p(f_0,g_0)+H_2(h,h^0)  \right\},
      \end{split}
    \end{equation}
    where $C$ is a constant depending on $n,p,q,\kappa,\lambda,\beta,\varrho,\Lambda_0,T,|\mathcal{O}|$ and $L$.

On the basis of the  monotone operator theory, Qiu and Tang in \cite{QiuTangBDSDES2010}
  established a theory of solvability for quasi-linear BSPDEs in an abstract framework.
  However even for the linear case $(f,g)\equiv (f_0,g_0)$,
  our BSPDE (\ref{1.1}) under assumptions $({\mathcal A}1)$--$({\mathcal A}3)$ falls beyond the framework of Qiu and Tang~\cite{QiuTangBDSDES2010}
  since our $b, c,$ and $\varsigma$ may be unbounded.

\label{propsition ito non null bdary}
      Let assumptions $({\mathcal A}1)$--$({\mathcal A}3)$ be satisfied,  $\left\{h^i,i=0,1,\cdots,n\right\}\subset \mathcal{M}^2(Q)$ and $(u,v)\in\mathscr{U}\times\mathscr{V}(G,f+h,g+h^0)$
      with $h=(h^1,\cdots,h^n)$ and $u^+\in \dot{\mathcal{V}}_{2,0}(Q)$. Let $\phi:\mathbb{R}\times\mathbb{R}^n\times\mathbb{R}\longrightarrow\mathbb{R}$ satisfy the assumptions of Lemma \ref{lem ito foumul}.
      Then, with probability 1, the following relation
\begin{equation*}
  \begin{split}
    &\int_{\mathcal{O}}\phi(t,x,u^+(t,x))\,dx+\frac{1}{2}\int_t^T\ll \phi''(s,\cdot,u^+(s)),\, |v^u(s)|^2\gg ds\\
    =&
    \int_{\mathcal{O}}\phi(T,x,G^+(x))\,dx-\int_t^T\int_{\mathcal{O}}\partial_{s}\phi(s,x,u^+(s,x))\,dxds
                   \\
    &-\int_{t}^T\ll \phi''(s,\cdot,u^+(s))\partial_{x_i} u^+(s)
    +\partial_{x_i} \phi'(s,\cdot,u^+(s)),\quad
    a^{ji}(s)\partial_{x_j}  u^+(s)\\
   &\quad\quad +\sigma^{ri}(s)v^{r,u}(s)+f^{i,u}(s)\gg \, ds\\
   &+\int_t^T\ll
        \phi'(s,\cdot,u^+(s)),\ b^i(s)\partial_{x_i}u^+(s)+c(s)\,u^+(s)+\varsigma^r(s)v^{r,u}(s)\gg ds\\
    &+\int_t^T\ll \phi'(s,\cdot,u^+(s)),\, g^{u}(s)\gg ds
    -\int_t^T\ll \phi'(s,\cdot,u^+(s)),\,v^{r,u}\gg dW_s^r
  \end{split}
\end{equation*}
holds almost surely for all $t\in[0,T]$
where
  \begin{equation*}
    \begin{split}
        &g^{u}(s,x):=1_{\{(s,x):u(s,x)>0\}}(s,x)\left(h^0(s,x)+g(s,x,u(s,x),\nabla u(s,x),v(s,x))\right);\\
        &f^{i,u}(s,x):=1_{\{(s,x):u(s,x)>0\}}(s,x)\left(h^i(s,x)+f^i(s,x,u(s,x),\nabla u(s,x),v(s,x))\right),\\
        &\ i=0,1,\cdots,n;
            \end{split}
  \end{equation*}
  and
  $$
 v^u:=(v^{1,u},\cdots,v^{m,u}), \quad v^{r,u}(s,x):=1_{\{(s,x):u(s,x)>0\}}(s,x)v^r(s,x),\ r=1,\cdots,m.
  $$

\label{thm max princip global 1}
  Let assumptions $({\mathcal A}1)$--$({\mathcal A}4)$  hold. Assume that $(u,v)\in\mathcal{V}_{2,0}(Q)\times\mathcal{M}^2(Q)$ is a weak solution of   (\ref{1.1}).
  Then we have
  \begin{equation}\label{estim thm max principle global 1}
    \operatorname*{ess\,sup}_{(\omega,t,x)\in\Omega\times Q}u(\omega,t,x)
    \,\leq C\left\{  \operatorname*{ess\,sup}_{(\omega,t,x)\in\Omega\times \partial_{\rm p}Q}u^+(\omega,t,x)
    +A_p(f_0,g_0^+)+\|u^+\|_{2;Q}\right\}
  \end{equation}
  where  $C$ is a constant  depending on
  $n,p,q,\kappa,\lambda,\beta,\varrho,\Lambda_0,L_0,T,|\mathcal{O}|$ and $L$.

In Theorem \ref{thm max princip global 1}, assume further that
  $$\operatorname*{ess\,sup}_{(\omega,t,x)\in\Omega\times \partial_{\rm p}Q}|u(\omega,t,x)|\,\leq L_1<\infty . $$
  We have
  $u\in \mathcal{L}^{\infty}(Q)$ and
  \begin{equation}\label{estim rmk max principle global 1}
    \|u\|_{\infty;Q}
    \,\leq C\left\{  L_1
    +A_p(f_0,g_0)+\|u\|_{2;Q}\right\}
  \end{equation}
  where $C$ is a constant  depending on
  $n,p,q,\kappa,\lambda,\beta,\varrho,\Lambda_0,L_0,T,|\mathcal{O}|$ and $L$.

We  use the induction principle. It is sufficient to prove the following assertion:
  \begin{equation}\label{eq in lem degiorgi iteration}
    a_k\leq \frac{\theta_0}{\nu^k},\,k=0,1,2,\cdots,
  \end{equation}
   with the parameter $\nu>1$ waiting to be determined later. It is obvious for $k=0$ that \eqref{eq in lem degiorgi iteration} holds. Assume that  \eqref{eq in lem degiorgi iteration} holds for $k=r$. Then we have
  $$a_{r+1}
  \leq C_0 b^r a_r^{1+\delta}
  \leq C_0 b^r \left(\frac{\theta_0}{\nu^r}\right)^{1+\delta}
  = \frac{\theta_0}{\nu^{r+1}} \cdot \frac{C_0b^r\theta_0^{\delta}}{\nu^{r\delta-1}}.
  $$
  Taking $\nu=b^{\frac{1}{\delta}}>1$, we obtain
  $$a_{r+1}\leq \frac{\theta_0}{\nu^{r+1}}\cdot C_0 \nu\theta_0^{\delta}=\frac{\theta_0}{\nu^{r+1}}.$$

Assume that $L_0=0$, or else we consider $\tilde{u}(t,x):=e^{L_0 t}u(t,x)$ instead of $u$.
  It is sufficient to prove our theorem for the case
  $$\operatorname*{ess\,sup}_{(\omega,t,x)\in\Omega\times \partial_{\rm p}Q}u^+(\omega,t,x) \, <\infty.$$
   Then for  $k\geq \operatorname*{ess\,sup}_{(\omega,t,x)\in\Omega\times \partial_{\rm p}Q}u^+(\omega,t,x)$, we have
  $(u-k,v)\in \mathscr{U}\times\mathscr{V}(G-k, f^k  , g^k  )$   with
  $$ ( f^k  , g^k  )(\omega,t,x,R,Y,Z):=(f,g)(\omega,t,x,R+k,Y,Z)+(0,c(\omega,t,x)k)
    $$
    for $(\omega,t,x,R,Y,Z)\in \Omega\times [0,T]\times\mathcal{O}\times\mathbb{R}\times\mathbb{R}^n\times\mathbb{R}^m$.
    From Proposition \ref{propsition ito non null bdary}, we have almost surely
    \begin{equation*}
      \begin{split}
      &\int_{\mathcal{O}}|(u(t,x)-k)^+|^2\,dx
      +\int_t^T\|v_k(s)\|^2_{L^2(\mathcal{O})}\,ds\\
      =&
      -2\int_t^T\ll \partial_{x_j} (u(s)-k)^+,\\
      &~~~~~~~a^{ij}\partial_{x_i} u(s)+\sigma^{jr}v^r_k(s)+ (f^k)^j(s,\cdot,(u(s)-k)^+,\nabla u(s),v_k(s))  \gg ds\\
      &+2\int_t^T\ll (u(s)-k)^+,\ b^i\partial_{x_i}u(s)+c\,(u(s)-k)^+ +\varsigma^r v_k^r(s)\gg ds\\
      &+2\int_t^T\ll (u(s)-k)^+,\  g^k  (s,\cdot,(u(s)-k)^+,\,\nabla u(s),v_k(s))   \gg ds\\
      &-2\int_t^T\ll (u(s)-k)^+,\ v_k^r(s)\gg dW_s^r,\quad \forall \ t\in [0,T]
      \end{split}
    \end{equation*}
    with $v_k:=v 1_{u>k}$.
    Therefore, we have
    \begin{equation}\label{eq ito square in thm glob maxim}
      \begin{split}
        &\int_{\mathcal{O}}|(u(t,x)-k)^+|^2\,dx
        +E\bigg[ \int_t^T\|v_k(s)\|^2_{L^2(\mathcal{O})}\,ds \big|\mathscr{F}_t\bigg]
        \\
        =&-2E\biggl[\int_t^T \ll \partial_{x_j} (u(s)-k)^+,\quad
      a^{ij}\partial_{x_i} u(s)+\sigma^{jr}v^r_k(s)\\
      &\quad\quad+ (f^k)  ^j(s,\cdot,(u(s)-k)^+,\nabla u(s),v_k(s)) \gg ds     \big|\mathscr{F}_t\bigg]\\
      &+2E\bigg[\int_t^T\ll (u(s)-k)^+,\ b^i\partial_{x_i}u(s)+c\,(u(s)-k)^+ +\varsigma^r v_k^r(s)\gg ds\big|\mathscr{F}_t\bigg]\\
      &+2E\bigg[\int_t^T\ll (u(s)-k)^+,\,  g^k  (s,\cdot,(u(s)-k)^+,\nabla u(s),v_k(s)) \gg ds \big|\mathscr{F}_t\biggr],\,a.s..
      \end{split}
    \end{equation}
    Note that
    \begin{equation}\label{eq 1 in thm glob max}
      \begin{split}
        &\operatorname*{ess\,sup}_{\Omega}\!\sup_{\tau\in[t,T]}2E\left[\int_{\tau}^T\ll (u(s)-k)^+,\,  g_0^k (s)\gg ds   \big|\mathscr{F}_{\tau}\right]\\
        \leq &
        \ 2\|( g_0^k )^+\|_{\frac{p(n+2)}{n+2+p};\mathcal{O}_t}\|(u-k)^+\|_{\frac{2(n+2)}{n};\mathcal{O}_t}
        \left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{\frac{1}{2}-\frac{1}{p}}~ \textrm{  (H$\ddot{\textrm{o}}$lder inequality)} \\
        \leq &
        \ \delta\|(u-k)^+\|^2_{\frac{2(n+2)}{n};\mathcal{O}_t}
        +C(\delta)\|( g_0^k )^+\|^2_{\frac{p(n+2)}{n+2+p};\mathcal{O}_t}
        \left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}}\\
        \leq &
        \ \delta\|(u-k)^+\|^2_{\frac{2(n+2)}{n};\mathcal{O}_t}
        +C(\delta,p,L)\left(\left|A_p(f_0,g_0^+)\right|^2+k^2\right)
        \left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}},
      \end{split}
    \end{equation}
    \begin{equation}\label{eq es linear global}
    \begin{split}
      &\operatorname*{ess\,sup}_{\omega\in\Omega}\!\!\sup_{\tau\in[t,T]}
      \!\!2E\left[\int_{\tau}^T\!\!\!\!\! \ll (u(s)-k)^+,\ b^i\partial_{x_i}u(s)+c\,(u(s)-k)^++\varsigma^rv^r_k(s) \gg \!ds
                    \big|\mathscr{F}_{\tau}\right]\\
      \leq &
      \ C(\varepsilon)\operatorname*{ess\,sup}_{\omega\in\Omega}\sup_{\tau\in[t,T]}
      \!E\left[\int_{\tau}^T\!\!\!\! \ll |b(s)|^2+|c(s)|+|\varsigma(s)|^2,\ \left|(u(s)-k)^+\right|^2 \gg \!ds
                    \big|\mathscr{F}_{\tau}\right]\\
      &+\varepsilon \left(\|\nabla (u-k)^+\|_{2;\mathcal{O}_t}^2
      +\|v_k\|_{2;\mathcal{O}_t}^2\right)\\
      \leq&
      \ \varepsilon \left(\|\nabla (u-k)^+\|_{2;\mathcal{O}_t}^2
      +\|v_k\|_{2;\mathcal{O}_t}^2\right)
      +C(\varepsilon)
      \Lambda_0 \|(u-k)^+\|^2_{\frac{2q}{q-1};\mathcal{O}_t} \\
      \leq&
      \ \varepsilon \left(\|\nabla (u-k)^+\|_{2;\mathcal{O}_t}^2
      +\|v_k\|_{2;\mathcal{O}_t}^2\right)+\delta \|(u-k)^+\|_{\frac{2(n+2)}{n};\mathcal{O}_t}^2\\
      &+
      C(\delta,n,q,\varepsilon,\Lambda_0)\|(u-k)^+\|_{2;\mathcal{O}_t}^2,
    \end{split}
  \end{equation}
   and
    \begin{equation}\label{eq 2 in thm glob max}
      \begin{split}
        &2E\left[\int_t^T\ll |\nabla (u(s)-k)^+|,\,| f_0^k (s)|\gg ds\Big|\mathscr{F}_t\right]\\
        \leq &
        \ \varepsilon E \left[\int_t^T\|\nabla (u(s)-k)^+\|^2_{L^2(\mathcal{O})}\,ds \Big|\mathscr{F}_t\right]
        +C(\varepsilon)E \left[ \int_t^T\| f_0^k 1_{u>k} (s)\|_{L^2(\mathcal{O})}^2\,ds \Big|\mathscr{F}_t\right] \\
        \leq &
        \ \varepsilon E \left[\int_t^T\|\nabla (u(s)-k)^+\|^2_{L^2(\mathcal{O})}\,ds \Big|\mathscr{F}_t\right]
        +C(\varepsilon)\left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}}\| f_0^k \|_{p;\mathcal{O}_t}^2\\
        \leq &
        \ \varepsilon E \left[\int_t^T\|\nabla (u(s)-k)^+\|^2_{L^2(\mathcal{O})}\,ds \Big|\mathscr{F}_t\right]  \\
        &+C(\varepsilon,p,L)\left(\left|A_p(f_0,g_0^+)\right|^2+k^2\right)
        \left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}},a.s.
      \end{split}
    \end{equation}
    where $\varepsilon $ and $\delta$ are two positive parameters waiting to be determined later and
    $$\left|\{u>k\}\right|_{\infty;\mathcal{O}_t}:=\operatorname*{ess\,sup}_{\Omega}\sup_{\tau\in[t,T]}
        E\left[ |Q_{\tau}\cap \{u>k\}|  \big| {\mathscr{F}_{\tau}}\right].$$
    In a similar way  to \eqref{eq est g} and \eqref{eq est principle part} in the proof of Theorem \ref{thm solve (1.1)}, we  obtain from \eqref{eq 1 in thm glob max}
    and \eqref{eq 2 in thm glob max} that with probability 1, for all $t\in[0,T]$
    \begin{equation}\label{eq 3 in thm glob max}
      \begin{split}
        &-2E\bigg[\int_t^T \ll \partial_{x_j} (u(s)-k)^+,\quad
      a^{ij}\partial_{x_i} u(s)+\sigma^{jr}v^r_k(s)\\
      &\quad\quad + (f^k)  ^j(s,\cdot,(u(s)-k)^+,\,\nabla u(s),v_k(s))  \gg  ds     \big|\mathscr{F}_t\bigg]\\
      \leq&
      -(\lambda-\kappa-\beta\theta-\varepsilon)E\bigg[ \int_t^T\|\nabla(u(s)-k)^+\|^2_{L^2(\mathcal{O})}\,ds\big|\mathscr{F}_t  \bigg]\\
      & +\left(\frac{1}{\varrho}+\frac{1}{\theta}\right)E\bigg[\int_t^T\|v_k(s)\|^2_{L^2(\mathcal{O})}\,ds \big|\mathscr{F}_t\bigg]\\
      &+C(\varepsilon,L)E\bigg[\int_t^T\|(u(s)-k)^+\|^2_{L^2(\mathcal{O})}\,ds  \big|\mathscr{F}_t\bigg]\\
      &+2E\bigg[\int_t^T(|\nabla (u(s)-k)^+|,| f_0^k (s)|)\,ds     \big|\mathscr{F}_t\bigg]                       \\
      \leq&
      -(\lambda-\kappa-\beta\theta-2\varepsilon)E\bigg[ \int_t^T\|\nabla(u(s)-k)^+\|^2_{L^2(\mathcal{O})}\,ds\big|\mathscr{F}_t  \bigg]\\
      &+\left(\frac{1}{\varrho}+\frac{1}{\theta}\right)E\bigg[\int_t^T\|v_k(s)\|^2_{L^2(\mathcal{O})}\,ds \big|\mathscr{F}_t\bigg]\\
      &+C(\varepsilon,L)E\bigg[\int_t^T\|(u(s)-k)^+\|^2_{L^2(\mathcal{O})}\,ds  \big|\mathscr{F}_t\bigg]\\
      &+C(\varepsilon,p,L)\left(\left|A_p(f_0,g_0^+)\right|^2+k^2\right)
        \left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}}
      \end{split}
    \end{equation}
    and
    \begin{equation}\label{eq 4 in thm glob max}
      \begin{split}
        &\operatorname*{ess\,sup}_{\Omega}\sup_{\tau\in[t,T]}2E\bigg[\int_{\tau}^T\ll (u(s)-k)^+,\, g^k  (s,\cdot,(u(s)-k)^+,\nabla u(s),v_k(s))\gg ds \big|\mathscr{F}_{\tau}\bigg]\\
        &\leq
        \varepsilon\|\nabla (u-k)^+\|_{2;\mathcal{O}_t}^2+\varepsilon_1\|v_k\|_{2;\mathcal{O}_t}^2+C(\varepsilon,\varepsilon_1,L)\|(u-k)^+\|^2_{2;\mathcal{O}_t}\\
        &~~+\operatorname*{ess\,sup}_{\Omega}\sup_{\tau\in[t,T]}2E\left[\int_{\tau}^T\ll (u(s)-k)^+,\, g_0^k (s)\gg ds   \big|\mathscr{F}_{\tau}\right]\\
        &\leq
        \varepsilon\|\nabla (u-k)^+\|_{2;\mathcal{O}_t}^2+\varepsilon_1\|v_k\|_{2;\mathcal{O}_t}^2+C(\varepsilon,\varepsilon_1,L)\|(u-k)^+\|^2_{2;\mathcal{O}_t}\\
        &~~
          +\delta \|(u-k)^+\|^2_{\frac{2(n+2)}{n};\mathcal{O}_t}+C(L,\delta,p)\left(\left|A_p(f_0,g_0^+)\right|^2+k^2\right)
        \left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}}
      \end{split}
    \end{equation}
    where $\theta$, $\varepsilon$, $\varepsilon_1$ and $\delta$ are four positive parameters such that
    $$\theta>\frac{\varrho}{\varrho-1}>1,
    \frac{1}{\varrho}+\frac{1}{\theta}+\varepsilon+\varepsilon_1<1
    \textrm{ and } \lambda-\kappa-\beta\theta-4\varepsilon>0.$$
    Combining \eqref{eq ito square in thm glob maxim}, \eqref{eq es linear global}, \eqref{eq 3 in thm glob max} and \eqref{eq 4 in thm glob max}, we have
    \begin{equation}\label{eq estim 1  thm glob max}
      \begin{split}
        &\|(u-k)^+\|^2_{\mathcal{V}_2(\mathcal{O}_t)}+\|v_k\|^2_{2;\mathcal{O}_t}\\
        \leq&
            \ C\bigg\{C(\delta)\|(u-k)^+\|^2_{2;\mathcal{O}_t}+\delta \|(u-k)^+\|^2_{\frac{2(n+2)}{n};\mathcal{O}_t} \\
            & \ \ \ \ +C(\delta ) \left(\left|A_p(f_0,g_0^+)\right|^2+k^2\right)
        \left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}} \bigg\},
      \end{split}
    \end{equation}
    where $C$ is a constant independent of $t$ and $\delta$.

     By Lemma \ref{lem emmbedding for space V}, $\mathcal{V}_{2,0}(\mathcal{O}_t)$ is continuously embedded into $\mathcal{M}^{\frac{2(n+2)}{n}}(\mathcal{O}_t)$.
     That is $$ \|(u-k)^+\|_{\frac{2(n+2)}{n};\mathcal{O}_t}\leq C \|(u-k)^+\|_{\mathcal{V}_2(\mathcal{O}_t)}. $$
     Therefore, choosing  $\delta$ to be small enough, we obtain
     \begin{equation*}
       \begin{split}
         \|(u-k)^+\|^2_{\frac{2(n+2)}{n};\mathcal{O}_t}
         \leq&
            C\|(u-k)^+\|^2_{2;\mathcal{O}_t}+C\left(\left|A_p(f_0,g_0^+)\right|^2+k^2\right)\left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}}\\
         \leq&
            C(|T-t||\mathcal{O}|)^{\frac{2}{n+2}}\|(u-k)^+\|^2_{\frac{2(n+2)}{n};\mathcal{O}_t}\\
            &+C\left(\left|A_p(f_0,g_0^+)\right|^2+k^2\right)\left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}}.\\
       \end{split}
     \end{equation*}
     Choosing $t_1\in[0,T)$ such that $C(|T-t_1||\mathcal{O}|)^{\frac{2}{n+2}} \leq \frac{1}{2}$, we get
     \begin{equation*}
       \begin{split}
         \|(u-k)^+\|^2_{\frac{2(n+2)}{n};\mathcal{O}_{t_1}}
         \leq \,
            C\left(\left|A_p(f_0,g_0^+)\right|^2+k^2\right)\left|\{u>k\}\right|_{\infty;\mathcal{O}_{t_1}}^{1-\frac{2}{p}}
       \end{split}
     \end{equation*}
     where the constant $C$ does not depend on $t_1$.

     Define
     $$\psi:\mathbb{R}\longrightarrow \mathbb{R},~~~\psi(h)=\left|\{u>h\}\right|_{\infty;\mathcal{O}_{t_1}}.$$
     Since for any $h>k$,
     $$\|(u-k)^+\|^2_{\frac{2(n+2)}{n};\mathcal{O}_{t_1}}
        \geq (h-k)^2 \left|\{u>h\}\right|_{\infty;\mathcal{O}_{t_1}}^{\frac{n}{n+2}},$$
     taking $k\geq A_p(f_0,g_0^+)$ we have
     \begin{equation*}
       \begin{split}
         \psi(h)^{\frac{n}{n+2}}\leq \frac{Ck^2}{(h-k)^2}\psi(k)^{1-\frac{2}{p}}
       \end{split}
     \end{equation*}
     which implies
     \begin{equation}\label{eq 5 in thm glob max}
       \begin{split}
         \psi(h)\leq \frac{Ck^{\alpha}}{(h-k)^{\alpha}}\psi(k)^{1+\bar{\varepsilon}}
       \end{split}
     \end{equation}
     where $\alpha=\frac{2(n+2)}{n}$ and $\bar{\varepsilon}=\frac{2(p-n-2)}{pn}>0$.
     Take $k_l=k(2-2^{-l})$, $l=0,1,2,\cdots.$
     Then from
     $$\psi(k_{l+1})\leq \frac{Ck_l^{\alpha}}{(k_{l+1}-k_l)^{\alpha}}\psi(k_l)^{1+\bar{\varepsilon}},$$
     it follows that
     \begin{equation*}
       \begin{split}
         \psi(k_{l+1})
         \leq
            \hat{C} 2^{\alpha(l+1)}\psi(k_l)^{1+\bar{\varepsilon}}.
       \end{split}
     \end{equation*}
                                                                
    By Lemma \ref{lem degiorgi iteration}, there exists a constant $\theta_0=\theta_0(\hat{C},\bar{\varepsilon})>0$, such that
    if $\psi(k_0)\leq \theta_0$, $\lim_{l\rightarrow\infty}\psi(k_l)=0$.
    Note that $k_0=k$ and $\psi(k_0)=\left|\{u>k\}\right|_{\infty;\mathcal{O}_{t_1} }$.

    Taking
    $$k=\operatorname*{ess\,sup}_{(\omega,s,x)\in\Omega\times \partial_{\rm p}Q}u^+(\omega,s,x)
    +A_p(f_0,g_0^+)+{\theta_0^{-\frac{1}{2}}}\|u^+\|_{2;\mathcal{O}_{t_1}},$$
     we have
    \begin{equation*}
      \begin{split}
        k^2
        \geq \frac{1}{\theta_0}\|u^+\|^2_{2;\mathcal{O}_{t_1}}
        \geq \frac{1}{\theta_0} k^2 \left|\{u>k\}\right|_{\infty;\mathcal{O}_{t_1}}
      \end{split}
    \end{equation*}
    which implies
    \begin{equation*}
      \begin{split}
        \psi(k_0)=\left|\{u>k\}\right|_{\infty;\mathcal{O}_{t_1}}\leq \theta_0.
      \end{split}
    \end{equation*}
     Hence, $\psi(k_{\infty})=0$. Since $k_{\infty}=2k$, we obtain
     \begin{equation*}
    \operatorname*{ess\,sup}_{(\omega,s,x)\in\Omega\times \mathcal{O}_{t_1}}\!\!\!u(\omega,s,x)\leq 2k
    = 2\left\{\!  \operatorname*{ess\,sup}_{(\omega,s,x)\in\Omega\times \partial_{\rm p}Q}  u^+(\omega,s,x)
    +A_p(f_0,g_0^+)+{\theta_0^{-\frac{1}{2}}}\|u^+\|_{2;Q}\right\}.
  \end{equation*}
  As $T-t_1$ only depends on the structure terms like $n,\lambda,\kappa,\beta,\varrho,p,q,L,\Lambda_0,|\mathcal{O}|$ and $T$, by induction, we get estimate \eqref{estim thm max principle global 1}.

\label{thm max princip global 2}
  Let assumptions $({\mathcal A}1)$--$({\mathcal A}4)$ be satisfied and  $(u,v)\in\mathcal{V}_{2,0}(Q)\times\mathcal{M}^2(Q)$ be a weak solution of   (\ref{1.1}). If
  $L_0=0$ and with probability 1
  \begin{equation}\label{condition in thm max princip 2}
    \begin{split}
      f(t,x,R,0,0)\equiv f(t,x,0,0)
       \textrm{ and }
       g(t,x,R,0,0) \textrm{ are decreasing in }  R\in \mathbb{R}
    \end{split}
  \end{equation}
  for all $(t,x)\in [0,T]\times\mathbb{R}^n$,
  then we assert
  \begin{equation}\label{estim in thm max princip global 2}
    \begin{split}
        \operatorname*{ess\,sup}_{(\omega,t,x)\in\Omega\times Q}u(\omega,t,x)
        \leq   \operatorname*{ess\,sup}_{(\omega,t,x)\in\Omega\times \partial_{\rm p}Q}u^+(\omega,t,x)
        +C A_p(f_0,g_0^+) |\mathcal{O}|^{\frac{1}{n+2}-\frac{1}{p}}
    \end{split}
  \end{equation}
  with the constant $C$ only depending on
  $n,p,q,\kappa,\lambda,\beta,\varrho,T,\Lambda_0$ and $L$.

We use  De Giorgi iteration and the same notations
  in the proof of Theorem \ref{thm max princip global 1}. Similar to the proof of \eqref{eq 1 in thm glob max}
  and \eqref{eq 2 in thm glob max},
  under condition \eqref{condition in thm max princip 2},
  we have for each $t\in [0,T]$,
  \begin{equation}\label{eq 1 in thm glob max 2}
      \begin{split}
        &\operatorname*{ess\,sup}_{\Omega}\sup_{\tau\in[t,T]}2E\left[\int_{\tau}^T\ll (u(s)-k)^+,\,\   g_0^k (s)\gg ds   \big|\mathscr{F}_{\tau}\right]\\
        \leq &
        \operatorname*{ess\,sup}_{\Omega}\sup_{\tau\in[t,T]}2E\left[\int_{\tau}^T\ll (u(s)-k)^+,\,\ g_0(s)\gg ds   \big|\mathscr{F}_{\tau}\right]\\
        \leq &
        \delta\|(u-k)^+\|^2_{\frac{2(n+2)}{n};\mathcal{O}_t}
        +C(\delta)\left|A_p(f_0,g_0^+)\right|^2
        \left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}}
      \end{split}
    \end{equation}
    and almost surely
    \begin{equation}\label{eq 2 in thm glob max 2}
      \begin{split}
        &2E\left[\int_t^T\ll |\nabla (u(s)-k)^+|,\,| f_0^k (s)|\gg ds\Big| \mathscr{F}_t\right]\\
        =&
        2E\left[\int_t^T\ll |\nabla (u(s)-k)^+|,\, |f_0(s)|\gg ds \Big| \mathscr{F}_t\right]\\
        \leq &
        \varepsilon E\left[\int_t^T\|\nabla (u(s)-k)^+\|^2_{L^2(\mathcal{O})}\, ds \Big| \mathscr{F}_t\right]
        +C(\varepsilon)\left|A_p(f_0,g_0^+)\right|^2
        \left|\{u>k\}\right|_{\infty;\mathcal{O}_t}^{1-\frac{2}{p}}.
      \end{split}
    \end{equation}
    Hence instead of \eqref{eq 5 in thm glob max}, we obtain
    \begin{equation*}
      \psi(h)\leq \frac{C\left|A_p(f_0,g_0^+)\right|^{\alpha}}{(h-k)^{\alpha}}\psi(k)^{1+\bar{\varepsilon}}.
    \end{equation*}
    By Corollary \ref{cor degiorgi iteration}, for any $\bar{\theta}_0\geq C A_p(f_0,g_0^+)|\mathcal{O}_{t_1}|^{\frac{1}{n+2}-\frac{1}{p}}$,
    we have
    \begin{equation}
      \begin{split}
        \left|\left\{u>\operatorname*{ess\,sup}_{(\omega,t,x)\in\Omega\times \partial_{\rm p}Q}u^+(\omega,t,x)
        +\bar{\theta}_0    \right\}\right|_{\infty;\mathcal{O}_{t_1}}=0,
      \end{split}
    \end{equation}
    which implies
    \begin{equation}
      \begin{split}
        \sup_{(\omega,t,x)\in\Omega\times \mathcal{O}_{t_1}}u
        \,\leq
        \sup_{(\omega,t,x)\in\Omega\times \partial_{\rm p}Q}u^++CA_p(f_0,g_0^+)|\mathcal{O}_{t_1}|^{\frac{1}{n+2}-\frac{1}{p}}
      \end{split}
    \end{equation}
    where the constant $C$ depends only on $n,\lambda,p,q,\beta,\kappa,\varrho,\Lambda_0$ and $L$.
    As $T-t_1$ only depends on the structure terms, by induction, we get estimate \eqref{estim in thm max princip global 2} where the constant $C$ also depends on $T$. We complete the proof.

$(u_1-u_2,v_1-v_2)$ belongs to $\mathscr{U}\times\mathscr{V}(\tilde{G},\tilde{f},\tilde{g})$ with
  \begin{equation*}
    \begin{split}
      \tilde{f}(s,x,R,Y,Z):=\, & f(s,x,R+u_2(s,x),Y+\nabla u_2(s,x),Z+v_2(s,x))\\
      &-f(s,x,u_2(s,x),\nabla u_2(s,x),v_2(s,x)),\\
      \tilde{g}(s,x,R,Y,Z):=\, &g^1(s,x,R+u_2(s,x),Y+\nabla u_2(s,x),Z+v_2(s,x))\\
      &-g^2(s,x,u_2(s,x),\nabla u_2(s,x),v_2(s,x))
    \end{split}
  \end{equation*}
  and  $\tilde{G}:=G^1-G^2$. Since $\tilde{G}\leq 0$, $\tilde{g}_0\leq 0$ and $f_0=0$, the assertion follows from Theorem \ref{thm max princip global 2}.

For domain $Q'\subset Q$, a function $\zeta(\cdot,\cdot)$ is called a cut-off function on $Q'$ if

  (i) $\zeta\in \dot{W}_1^{2,2}(Q')$, i.e. there exists a sequence $\{\zeta^l,l\in\mathbb{N}\}\subset C_c^{\infty}(Q')$ such that
  \begin{equation}
    \begin{split}
      \|\zeta^l-\zeta\|_{W_1^{2,2}}:=
      \bigg\{\int_{Q'}\Big(& |(\zeta^l-\zeta)(t,x)|^2+|\partial_{t}(\zeta^l-\zeta)(t,x)|^2\\
      &+
        |\nabla (\zeta^l-\zeta)(t,x)|^2+|\nabla^2(\zeta^l-\zeta)(t,x)|^2\Big)\,dxdt \bigg\}^{\frac{1}{2}}
            \end{split}
  \end{equation}
  converges to zero as $l$ tends to infinity with $\nabla^2(\zeta^l-\zeta)(t,x)$ being the Hessian matrix of the function $(\zeta^l-\zeta)(t, \cdot)$ at $x$;

  (ii) $0\leq \zeta \leq 1 $;

  (iii) there exists a  domain  $ Q''\Subset Q'$ and a nonempty domain $Q'''\Subset Q''$ such that
     \begin{equation*}
    \zeta(t,x)=
  \left\{\begin{array}{l}
    \begin{split}
        &1,\quad (t,x)\in Q''',\\
        &0,\quad (t,x)\in Q'\setminus Q'';
    \end{split}
  \end{array}\right.
  \end{equation*}

  (iv) $|\nabla \zeta|,\partial_{t}\zeta \in L^{\infty}(Q')$.

  For simplicity, we denote
  $$ \|\nabla \zeta\|_{L^{\infty}(Q')}:=\| |\nabla \zeta|  \|_{L^{\infty}(Q')}. $$

We say that a function $u\in\mathcal{V}_{2,0}(Q)$ belongs to the backward stochastic parabolic De Giorgi class (BSPDG, for short)
   if for any $k\in\mathbb{R}$, $Q_{\rho,\tau}:=[t_0-\tau,t_0)\times B_{\rho}(x_0) \subset Q$ (with $\rho,\tau\in (0,1)$)
   and any cut-off function $\zeta$ on $Q_{\rho,\tau}$, we have
   \begin{equation*}
  \begin{array}{l}
    \begin{split}
           &\|\zeta(u-k)^{\pm}\|^2_{\mathcal{V}_{2}(Q_{\rho,\tau})}\\
       \leq
       &\gamma\Big\{\|(u-k)^{\pm}\|^2_{2;Q_{\rho,\tau}}
       (1+\|\nabla\zeta\|_{L^{\infty}(Q_{\rho,\tau})}^2
            +\|\partial_{t}\zeta\|_{L^{\infty}(Q_{\rho,\tau})}  )\\
       &\quad +(k^2+a_0^2)|\{ (u-k)^{\pm}>0\}|_{\infty;Q_{\rho,\tau}}^{1-\frac{2}{\mu}}   \Big\}
    \end{split}
  \end{array}
  ~~~~~~~(\mathfrak{D}^{\pm})
  \end{equation*}
  for some triplet $(a_0, \mu, \gamma) \in [0, \infty)\times (n+2, \infty)\times [0, \infty)$.
  We  call $a_0,\mu,$ and $\gamma$ the structural parameters of $BSPDG^{\pm}$. We mean that $u\in\mathcal{V}_{2,0}(Q)$
  satisfies $(\mathfrak{D}^{+})$ ($(\mathfrak{D}^-)$, respectively) by the inclusion $u\in BSPDG^+(a_0, \mu, \gamma;Q)$
  ($u\in BSPDG^-(a_0, \mu, \gamma;Q)$, respectively). We say $u\in BSPDG(a_0, \mu, \gamma;Q)$ if both inclusions $u\in BSPDG^+(a_0, \mu, \gamma;Q)$
  and $u\in BSPDG^-(a_0, \mu, \gamma;Q)$ hold.

\label{lem cor of prop ito non null bdary}
     Let assumptions $({\mathcal A}1)$--$({\mathcal A}3)$ hold, $\zeta$ be a cut-off function
     on $Q_{\rho,\tau}:=[t_0-\tau,t_0)\times B_{\rho}(x_0) \subset Q$, and $(u,v)\in\mathcal{V}_{2,0}(Q)\times\mathcal{M}^2(Q)$
     be a weak solution of   (\ref{1.1}). Then, we have almost surely
\begin{equation}\label{eq ito cutoff func}
  \begin{split}
    &\ll \zeta^2(t),\, |u^+(t)|^2\gg_{B_{\rho}(x_0)}+\int_t^{t_0}\ll \zeta^2(s),\,|v^u(s)|^2\gg_{B_{\rho}(x_0)} ds\\
    =&
                                                
    -\int_t^{t_0}2\ll \zeta \partial_{s}\zeta(s),\ \, |u^+(s)|^2\gg_{B_{\rho}(x_0)} ds\\
    &+\int_t^{t_0}2\ll \zeta^2(s) u^+(s),\ \,g^{u}(s)\gg_{B_{\rho}(x_0)}ds               \\
    &+\int_t^{t_0}2\ll \zeta^2(s) u^+(s),\ \,   b^i(s)\partial_{x_i}u(s)+c(s)\,u^+(s)+\varsigma^r(s) v^{r,u}(s)\gg_{B_{\rho}(x_0)} ds\\
    &-\int_{t}^{t_0}\ll 2\partial_{x_i} (\zeta^2(s)u^+(s)),\ \,
            a^{ji}(s)\partial_{x_j}  u^+(s)
            +\sigma^{ir}(s)v^{r,u}(s)
            +f^{i,u}(s)\gg_{B_{\rho}(x_0)}ds\\
    &-\int_t^{t_0}2\ll \zeta^2(s)u^+(s),\ \, v^{r,u}(s)\gg_{B_{\rho}(x_0)} dW_s^r, \quad \forall \, t\in [t_0-\tau, t_0]
  \end{split}
\end{equation}
where
 \begin{equation*}
    \begin{split}
        &g^{u}(s,x):=1_{\{(s,x):u(s,x)>0\}}(s,x)g(s,x,u(s,x),\nabla u(s,x),v(s,x));\\
        &f^{i,u}(s,x):=1_{\{(s,x):u(s,x)>0\}}(s,x)f^i(s,x,u(s,x),\nabla u(s,x),v(s,x)),\ i=0,1,\cdots,n;\\
    \end{split}
  \end{equation*}
  and
 $$ v^u:=(v^{1,u},\cdots,v^{m,u}), \quad v^{r,u}(s,x):=1_{\{(s,x):u(s,x)>0\}}(s,x)v^r(s,x),\quad  r=1,\cdots,m.$$

\label{thm max princip local}
  If $u\in BSPDG^{\pm}(a_0, \mu, \gamma;Q)$, we assert that for any
  $$ Q_{\rho}=[t_0,t_0+\rho^2)\times B_{\rho}(x_0) \subset Q,\,\rho\in (0,1), $$
  there holds
  \begin{equation}\label{estim in thm max princip local}
    \operatorname*{ess\,sup}_{\Omega\times Q_{\frac{\rho}{2}}} u^{\pm}
    \,\leq
        C\left\{  {\rho^{-\frac{n+2}{2}}} \|u^{\pm}\|_{2;Q_{\rho}}+a_0 \rho^{1-\frac{n+2}{\mu}}   \right\},
  \end{equation}
  where $C$ is a constant depending only on $a_0, \mu, \gamma$ and $n$.

Consider $u\in BSPDG^+(a_0, \mu, \gamma;Q)$.
  Take
  $$R_l=\frac{\rho}{2}+\frac{\rho}{2^{l+1}},\,k_l=k(2-\frac{1}{2^l}),\,l=0,1,2,\cdots  $$
  where $k$ is a parameter waiting to be determined later.
  Denote $Q^l:=Q_{R_l}=[t_0,t_0+R_l^2)\times B_{R_l}(x_0) $. Choose $\zeta_l$ to be a cut-off function on $Q^l$ such that
  \begin{equation*}
    \zeta_l(t,x)=
  \left\{\begin{array}{l}
    \begin{split}
        &1,\quad (t,x)\in Q^{l+1};\\
        &0,\quad (t,x)\in Q^l \setminus Q_{\frac{R_l+R_{l+1}}{2}}
    \end{split}
  \end{array}\right.
  \end{equation*}
  and
  $$\left\|\nabla \zeta_l  \right\|^2_{L^{\infty}(Q_{\rho})}+\left\| \partial_{t}\zeta_l  \right\|_{L^{\infty}(Q_{\rho})}
  \leq \frac{C(n)}{(R_l-R_{l+1})^2}.$$

  From $(\mathfrak{D}^+)$, it follows that
  \begin{equation*}
    \begin{split}
      &\|\zeta_l (u-k_{l+1})^+\|^2_{\mathcal{V}_2(Q^l)}\\
      \leq \,\,&
        C2^{2l}{\rho^{-2}}\|(u-k_{l+1})^+\|^2_{2;Q^l}
        +C(k^2+a_0^2)|\{u>k_{l+1}\}|^{1-\frac{2}{\mu}}_{\infty;Q^l}.
    \end{split}
  \end{equation*}
  For $k\geq a_0\rho^{1-\frac{n+2}{\mu}}$, we obtain from Lemma~\ref{lem emmbedding for space V} that
  \begin{equation*}
    \begin{split}
      &\|\zeta_l (u-k_{l+1})^+\|^2_{\frac{2(n+2)}{n};Q^l}\\
      \leq\  &
        C\|\zeta_l (u-k_{l+1})^+\|^2_{\mathcal{V}_2(Q^l)}\\
      \leq \ &
      C2^{2l}{\rho^{-2}}\|(u-k_{l+1})^+\|^2_{2;Q^l}
      + Ck^2 {\rho^{-2(1-\frac{n+2}{\mu})}}|\{u>k_{l+1}\}|^{1-\frac{2}{\mu}}_{\infty;Q^l}.
    \end{split}
  \end{equation*}
  Setting
  $$ \phi_l:=\|(u-k_l)^+\|^2_{2;Q^l},  $$
we have
  \begin{equation*}
    \begin{split}
      \phi_{l+1}
      \leq\ & \|\zeta_l(u-k_{l+1})^+\|_{2;Q^l}^2\\
      \leq\  & |\{u>k_{l+1}\}|^{\frac{2}{n+2}}_{\infty;Q^l}\|\zeta_l(u-k_{l+1})^+\|^2_{\frac{2(n+2)}{n};Q^l}
      ~\textrm{  (H$\ddot{\textrm{o}}$lder inequality)}\\
      \leq\  &
      C2^{2l}{\rho^{-2}}\phi_l |\{u>k_{l+1}\}|^{\frac{2}{n+2}}_{\infty;Q^l}
      + Ck^2 {\rho^{-2(1-\frac{n+2}{\mu})}}|\{u>k_{l+1}\}|^{1-\frac{2}{\mu}+\frac{2}{n+2}}_{\infty;Q^l}.
    \end{split}
  \end{equation*}
  Note that
  \begin{equation*}
    \begin{split}
      \phi_l
      =\|(u-k_l)^+\|^2_{2;Q^l}
      \geq\ &
      (k_{l+1}-k_l)^2 |\{u>k_{l+1}\}|_{\infty;Q^l}
      = k^2{2^{-(2l+2)}} |\{u>k_{l+1}\}|_{\infty;Q^l}.
    \end{split}
  \end{equation*}
  Hence,
  \begin{equation*}\label{eq a in thm max princip local}
    \begin{split}
      \phi_{l+1}
      \leq\ &
       C2^{2l(1+\frac{2}{n+2})} \left[
      {\rho^{-2} k^{-\frac{4}{n+2}}}{\phi_l^{1+\frac{2}{n+2}}}
      +
      {\rho^{-2(1-\frac{n+2}{\mu})}k^{\frac{4}{\mu}-\frac{4}{n+2}}}
      {\phi_l^{1-\frac{2}{\mu}+\frac{2}{n+2}}}
      \right]\\
      =\ &
        C2^{2l(1+\frac{2}{n+2})}
        {\rho^{-2(1-\frac{n+2}{\mu})}k^{\frac{4}{\mu}-\frac{4}{n+2}}}
        {  \phi_l^{1-\frac{2}{\mu}+\frac{2}{n+2}}}
      \left[\left({k^{-2} \rho^{-n-2}}{\phi_l}\right)^{\frac{2}{\mu}}  +1
      \right] .
    \end{split}
  \end{equation*}

  For $k\geq a_0\rho^{1-\frac{n+2}{\mu}}+ {\rho^{-\frac{n+2}{2}}}\|u^+\|_{2;Q_{\rho}}$,
  we have ${k^{-2}\rho^{-n-2}}{\phi_l} \leq 1$
  and therefore
  \begin{equation*}\label{eq b in thm max princip local}
    \begin{split}
      \phi_{l+1} \leq
      C 2^{2l(1+\frac{2}{n+2})}
      {\rho^{-2(1-\frac{n+2}{\mu})}k^{\frac{4}{\mu}-\frac{4}{n+2}}}
      { \phi_l^{1-\frac{2}{\mu}+\frac{2}{n+2}}}
      .
    \end{split}
  \end{equation*}
  Setting
  $$
  \alpha_l:=\rho^{-n-2}k^{-2}{\phi_l},
  $$
  we have
  $$
  \alpha_{l+1}\leq C_1 2^{2l(1+\frac{2}{n+2})} \alpha_l^{1-\frac{2}{\mu}+\frac{2}{n+2}}.
  $$
  From Lemma \ref{lem degiorgi iteration}, we see that the following
  \begin{equation*}
    \begin{split}
      \alpha_0 = &{k^{-2}\rho^{-n-2}}{\|(u-k)^+\|^2_{2;Q_{\rho}}}
      \ \leq\
      {k^{-2}\rho^{-n-2}}{\|u^+\|^2_{2;Q_{\rho}}}
      \ \leq\
      \theta_0: = C_1^{-\frac{1}{\alpha}}2^{-\frac{2}{\alpha^2}(1+\frac{2}{n+2})}
    \end{split}
  \end{equation*}
  with $\alpha:=\frac{2}{n+2}-\frac{2}{\mu}$, implies
  $$\lim_{l\rightarrow\infty}\alpha_l=0\textrm{ and thus }\lim_{l\rightarrow\infty}\phi_l=0.$$

  In conclusion, the two inequalities
  $$k^2\geq {\theta_0}^{-1} \rho^{-n-2}  {\|u^+\|_{2;Q_{\rho}}^2}
 \textrm{ and }
 k\geq a_0\rho^{1-\frac{n+2}{\mu}}+ \rho^{-\frac{n+2}{2}}\|u^+\|_{2;Q_{\rho}}$$
  imply the following one:
  \begin{equation}\label{eq c in thm max princip local}
    \begin{split}
      \|u\|_{\infty;Q_{\frac{\rho}{2}}}\leq 2k.
    \end{split}
  \end{equation}
  Hence, \eqref{eq c in thm max princip local} holds for the following choice
  $$k:=a_0 \rho^{1-\frac{n+2}{\mu}}+\left(1+{\theta_0^{-\frac{1}{2}}}\right) {\rho^{-\frac{n+2}{2}}}{\|u^+\|_{2;Q_{\rho}}}.$$
  which implies our desired estimate.

  For $u\in BSPDG^-(a_0, \mu, \gamma;Q)$, the desired assertion follows in a similar way. We complete our proof.
